13	    private static void bfsComponent(Graph graph, int source, boolean[] visited, List<Integer> result) {
14	        Deque<Integer> queue = new ArrayDeque<>();
15	        visited[source] = true;
16	        queue.addLast(source);
17	
18	        while (!queue.isEmpty()) {
19	            int current = queue.removeFirst();
20	            result.add(current);
21	
22	            for (int neighbor : graph.neighbors(current)) {
23	                if (!visited[neighbor]) {
24	                    visited[neighbor] = true;
25	                    queue.addLast(neighbor);
26	                }
27	            }
28	        }
29	    }
30	
31	    public static List<Integer> bfs(Graph graph) {
32	        Objects.requireNonNull(graph, "graph");
33	
34	        int vertexCount = graph.vertexCount();
35	        boolean[] visited = new boolean[vertexCount];
36	        List<Integer> result = new ArrayList<>(vertexCount);
37	
38	        for (int vertex = 0; vertex < vertexCount; vertex++) {
39	            if (!visited[vertex]) {
40	                bfsComponent(graph, vertex, visited, result);
41	            }
42	        }
43	        return result;
44	    }
45	
46	    public static List<Integer> bfsFromSource(Graph graph, int source) {
47	        Objects.requireNonNull(graph, "graph");
48	        if (!graph.containsVertex(source)) {
49	            throw new IllegalArgumentException("vertex out of bounds: " + source);
50	        }
51	
52	        boolean[] visited = new boolean[graph.vertexCount()];
53	        List<Integer> result = new ArrayList<>(graph.vertexCount());
54	        bfsComponent(graph, source, visited, result);
55	        return result;
56	    }
57	}

